package com.tapeverify.copilot.controller;
import com.tapeverify.copilot.dto.*; import com.tapeverify.copilot.repository.UserRepository; import com.tapeverify.copilot.security.JwtService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final UserRepository users; private final PasswordEncoder passwords; private final JwtService jwt; public AuthController(UserRepository users,PasswordEncoder passwords,JwtService jwt){this.users=users;this.passwords=passwords;this.jwt=jwt;} @PostMapping("/login") public AuthResponseDto login(@Valid @RequestBody LoginDto input){var u=users.findByUsername(input.getUsername()).filter(x->x.isActive()&&passwords.matches(input.getPassword(),x.getPasswordHash())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));return AuthResponseDto.builder().token(jwt.token(u)).username(u.getUsername()).role(u.getRole().name()).build();} }
